// 双方向リンク計算
window.LINKS = (() => {
  const set = new Set();
  const links = [];
  window.TERMS.forEach(term => {
    term.related.forEach(relId => {
      const key = [term.id, relId].sort().join("--");
      if (!set.has(key) && window.TERMS.find(t => t.id === relId)) {
        set.add(key);
        links.push({ source: term.id, target: relId });
      }
    });
  });
  return links;
})();
